    internal static byte[] Get(string key, int size)
    {
        string encoded = (key.ToUpperInvariant(), size) switch
        {
            ("L1", 64) => L1_64,
            ("L1", 32) => L1_32,
            ("L2", 64) => L2_64,
            ("L2", 32) => L2_32,
            ("R1", 64) => R1_64,
            ("R1", 32) => R1_32,
            ("R2", 64) => R2_64,
            ("R2", 32) => R2_32,
            _ => throw new ArgumentOutOfRangeException(nameof(key), $"Unknown DualShock artwork {key}/{size}."),
        };
        return Convert.FromBase64String(encoded);
    }
